function createLRUCache(capacity) {
  const map = new Map();
  return {
    get: function(key) {
      if (!map.has(key)) return -1;
      const val = map.get(key);
      map.delete(key);
      map.set(key, val);
      return val;
    },
    put: function(key, val) {
      if (map.has(key)) map.delete(key);
      map.set(key, val);
      if (map.size > capacity) {
        const oldest = map.keys().next().value;
        map.delete(oldest);
      }
    }
  };
}
